import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-kgbv-hostel',
  templateUrl: './kgbv-hostel.page.html',
  styleUrls: ['./kgbv-hostel.page.scss'],
})
export class KgbvHostelPage implements OnInit {

  menuLists: any[] = [];

  constructor(private router: Router) { }

  ngOnInit() {
  }

  ionViewDidEnter(){
    this.getMenuList();
  }

  getMenuList() {
    this.menuLists = [
      {
        menu: "Student Attendance",
        image: "../../../../assets/icons/student.svg",
        mod1: 71,   
        url:'/tabs/hostel-student-attendance'
      },
      {
        menu: "Staff Attendance",
        image: "../../../../assets/icons/teacher.svg",
        mod1: 72,
        url: "/tabs/hostel-staff-attendance",
      }
    ];
  }

  goHome(){
    this.router.navigate(['/tabs/home']);
  }

  navigatePage(item){
    this.router.navigate([item.url]);
  }

}
